export type ToolbarId = string;
export type ToolbarOrders = (ToolbarList | ToolbarItemId)[][];
export type ToolbarsOrders = Record<ToolbarId, ToolbarOrders>;
export interface ToolbarsPreset {
    items: ToolbarsItems;
    orders: ToolbarsOrders;
}
export {};

