.main { max-width: 1120px; margin: auto; padding: var(--g-spacing-8) var(--g-spacing-6); }
.breadcrumb { display: flex; gap: var(--g-spacing-3); margin-bottom: var(--g-spacing-8); }
.page-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-8); }
