.note-form { background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); padding: var(--g-spacing-7); }
.form-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); padding-bottom: var(--g-spacing-6); border-bottom: 1px solid var(--g-color-line-generic); }
.form-heading h2 { margin: 0 0 var(--g-spacing-2); }
.title-field { display: flex; flex-direction: column; gap: var(--g-spacing-3); padding: var(--g-spacing-6) 0; }
.content-heading { display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-4); }
.content-heading h3 { margin: 0 0 var(--g-spacing-2); }
.editor-shell { border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); overflow: hidden; }
.editor-shell:focus-within { border-color: var(--g-color-line-brand); }
.editor-tabs { display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-3); padding: var(--g-spacing-3); border-bottom: 1px solid var(--g-color-line-generic); background: var(--g-color-base-generic-ultralight); flex-wrap: wrap; }
.mode-buttons { display: flex; gap: var(--g-spacing-2); flex-wrap: wrap; }
.live-status { display: flex; gap: var(--g-spacing-2); align-items: center; color: var(--g-color-text-secondary); font-size: var(--g-text-caption-2-font-size); padding-right: var(--g-spacing-2); }
.live-status > span { width: 6px; height: 6px; border-radius: 50%; background: var(--g-color-text-positive); }
.editor-body { height: 360px; padding: var(--g-spacing-3); overflow: auto; --g-md-editor-padding: var(--g-spacing-3); --g-md-toolbar-padding: var(--g-spacing-2); }
.preview { padding: var(--g-spacing-4); min-width: 0; overflow-wrap: anywhere; }
.preview-caption { letter-spacing: 1px; display: block; margin-bottom: var(--g-spacing-5); }
.preview pre { overflow-x: auto; }
.preview img { max-width: 100%; }
.editor-footer { display: flex; justify-content: space-between; gap: var(--g-spacing-3); padding: var(--g-spacing-3) var(--g-spacing-4); border-top: 1px solid var(--g-color-line-generic); }
.form-actions { display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); margin-top: var(--g-spacing-6); }
.form-actions > div { min-width: 0; flex: 1; }
.form-actions > button { flex-shrink: 0; }
.help-card { margin-top: var(--g-spacing-6); padding: var(--g-spacing-6) var(--g-spacing-7); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); }
.help-heading { display: flex; flex-direction: column; gap: var(--g-spacing-2); }
